import dspy
from dspy.adapters.types.tool import ChatAdapter

# 1. Define tools with schemas matching your Python functions  
def search_db(query):  
    # Your custom function logic here  
    pass  

search_schema = {
    "type": "object",
    "properties": {"query": {"type": "string"}},
    "required": ["query"]
}

# 2. Planner class scoped to ONE call  
class ToolPlanner(dspy.Predict):  
    def __init__(self):  
        super().__init__(  
            template="Return ONLY raw JSON with NO markdown or brackets:\n{{\n \"tool_calls\": [{{"name": "{func}", \"args\": {{...}}}}]\n}}",  
            input={"prompt_template": "Plan these tasks: {}"},  
            output={"tool_calls": dspy.OutputField(desc="JSON array of tool calls", type=dict)}  
        )  
        self.adapter = ChatAdapter(use_native_function_calling=True)  

    def forward(self, task, tool_inventory):  
        self.predictions = []  
        result = super().forward(task, tool_inventory)  
        if hasattr(result, "tool_calls"):  
            self.predictions.extend(result.tool_calls)  
        return self.predictions  

planner = ToolPlanner()  

# Execute plan  
tool_registry = {"search_db": search_db}  
plan_output = planner.predict(  
    task="Analyze user query",  
    tool_inventory=[  
        {"name": "search_db", "schema": search_schema}  
    ]  
)  

for call in plan_output:  
    tool_registry[call["name"]](**call["args"])  
```  
**Key fixes:**  
- ✅ Adapter attached to instance, not globally.  
- ✅ All fields use `OutputField` for forced JSON.  
- ✅ Template explicitly bans markdown/bracketed text.  
- ✅ Tool schemas align with function signatures (avoid `'answer'` errors).  
- ✅ Rest of app remains untouched with default chat settings.

