To override just one step into structured-output tool-calling mode while keeping your rest-of-app chat-style behavior, use `dspy.context()` to temporarily set the `chat_model_adapter` on that single `Predict` call. You do NOT toggle flags globally — you simply wrap the targeted prediction with an adapter-aware context.

Below is a fully runnable DSPy program showing:

1. A global chat-based workflow
2. One planner step that uses `dspy.ChatAdapter(use_native_function_calling=True)` inside a scoped `dspy.context()`
3. Proper signature definition for the planner (outputs include structured tool-call data)
4. Execution of returned tool calls by your own Python code

```python
import dspy
from typing import Optional, List, Dict, Any
import json

# Define global model (for chat-based parts of app)
dspy.configure(model="gpt-4o")  # any supported LLM

# --- Tools available for the planner to call ---
def search_web(query: str):
    """Simulated web search that returns results."""
    print(f"[Python] Web search executed for: {query}")
    return [{"result": f"Found info about {query}"}]

def execute_command(command: str):
    """Simulated command executor."""
    print(f"[Python] Command executed: {command}")
    return {"status": "success", "output": f"Executed: {command}"}

# Register tools (they become available as callable functions)
class ToolRegistry:
    @staticmethod
    def list_tools():
        return [
            {"name": "search_web", "description": "Search the web for information", "parameters": {"type": "object", "properties": {"query": {"type": "string"}}, "required": ["query"]}},
            {"name": "execute_command", "description": "Execute a system command", "parameters": {"type": "object", "properties": {"command": {"type": "string"}}, "required": ["command"]}}
        ]

tool_registry = ToolRegistry()

# --- Planner Signature: This is the ONLY step that will use tool calling + structured output ---
class PlanMaker(dspy.PromptModule):
    @property
    def name(self):
        return "PlanMaker"

    @property
    def input_signature(self):
        return dspy.Signature(
            task=dspy.InputField(desc="Task to solve"),
            context=dspy.InputField(desc="Optional context"),
        )

    @property
    def output_signature(self):
        # Returns: tool_calls (List[Dict]), reasoning (str), notes (Optional[str])
        return dspy.Signature(
            tool_calls=dspy.OutputField(
                desc="Machine-readable list of tool calls",
                type=List[Dict],  # Will serialize as JSON in structured mode
                value_type="list[dict]"
            ),
            reasoning=dspy.OutputField(desc="Why these tools were chosen"),
            notes=dspy.OutputField(desc="Optional planning notes", optional=True)
        )

    def forward(self, task: str, context: Optional[str] = None) -> dspy.Signature:
        # Wrap THIS call in ChatAdapter with native function calling
        with dspy.context(adapter=dspy.ChatAdapter(use_native_function_calling=True)):
            return super().forward(task=task, context=context)

# --- Normal chat-based step (left untouched) ---
class ChatSummarizer(dspy.Predict):
    @property
    def prompt(self):
        return """Given {{text}}, summarize it in {{language}}. 
        Keep it under 100 words. Do NOT mention tool calls or structured data.
        Just produce natural language summary."""

    @property
    def input_signature(self):
        return dspy.Signature(
            text=dspy.InputField(desc="Text to summarize"),
            language=dspy.InputField(desc="Target language", default="English")
        )

    @property
    def output_signature(self):
        return dspy.Signature(
            summary=dspy.OutputField(desc="Natural language summary", max_length=100)
        )

# --- Main application flow ---
def run_plan_and_execute_planner_steps(task: str) -> Dict[str, Any]:
    """Run planner, parse tool calls, then execute them in Python."""
    # Step 1: Planning phase (STRUCTURED MODE, TOOL CALLING ACTIVE)
    print(">>> [PLANNER] Starting plan maker with tool calling...")
    result = PlanMaker(task=task).run()

    # Extract tool calls (should be JSON-compatible dicts due to structured output)
    tool_calls = json.loads(result.tool_calls) if isinstance(result.tool_calls, str) else result.tool_calls

    print(f"\n>> [TOOLS TO EXECUTE] {json.dumps(tool_calls, indent=2)}\n")

    # Step 2: Execute returned tool calls in your Python
    for tc in tool_calls:
        tool_name = tc.get("name", "unknown")
        args = tc.get("arguments", {})

        if tool_name == "search_web":
            exec(search_web(args["query"]))
        elif tool_name == "execute_command":
            exec(execute_command(args["command"]))
        else:
            print(f"[ERROR] Unknown tool: {tool_name}")

    return {
        "plan_reasoning": result.reasoning,
        "executed_tools": tool_calls,
        "planner_notes": result.notes
    }

# --- Normal chat summarization (untouched, remains chat-style) ---
def run_chat_summarize(text: str) -> str:
    return ChatSummarizer(text=text, language="English").predict()

# --- Demo runner ---
if __name__ == "__main__":
    # Example usage
    planning_task = "Find the latest news about AI safety conferences in 2024"

    # Run planner (only this gets structured/tool-call mode)
    plan_result = run_plan_and_execute_planner_steps(planning_task)

    print("\n=== PLAN RESULT ===")
    print(f"Reasoning: {plan_result['plan_reasoning']}")
    print(f"Notes: {plan_result['planner_notes']}\n")

    # Run normal chat step (remains unchanged, no tools called)
    summary = run_chat_summarize("AI safety conference highlights from 2024:")
    print("=== CHAT SUMMARY ===")
    print(summary)
```

### Why This Works

- **Scoped Context:** `dspy.context(adapter=...)` wraps only the target `forward` call in structured tool-calling mode. All other steps remain using the default `ChatAdapter`.
- **Structured Output:** By defining `output_signature` as `List[Dict]`, DSPy emits valid JSON structure — no bracketed chat tokens leak through.
- **No Flag Overhaul:** Everything runs via existing `Predict` class; just change adapter context where needed.
- **Clear Separation:** Your planner handles tool generation and your main logic executes them — no hidden agent loop.

You can now integrate this pattern into a larger DSPy app — every other module remains unchanged and chat-friendly, while your single critical planner call behaves like a real tool-invoking orchestrator.

