        Just produce natural language summary."""

    @property
    def input_signature(self):
        return dspy.Signature(
            text=dspy.InputField(desc="Text to summarize"),
            language=dspy.InputField(desc="Target language", default="English")
        )

    @property
    def output_signature(self):
        return dspy.Signature(
            summary=dspy.OutputField(desc="Natural language summary", max_length=100)
        )

# --- Main application flow ---
def run_plan_and_execute_planner_steps(task: str) -> Dict[str, Any]:
