    tool_calls = json.loads(result.tool_calls) if isinstance(result.tool_calls, str) else result.tool_calls

    print(f"\n>> [TOOLS TO EXECUTE] {json.dumps(tool_calls, indent=2)}\n")

    # Step 2: Execute returned tool calls in your Python
    for tc in tool_calls:
        tool_name = tc.get("name", "unknown")
        args = tc.get("arguments", {})

        if tool_name == "search_web":
            exec(search_web(args["query"]))
        elif tool_name == "execute_command":
            exec(execute_command(args["command"]))
        else:
            print(f"[ERROR] Unknown tool: {tool_name}")

    return {
        "plan_reasoning": result.reasoning,
        "executed_tools": tool_calls,
        "planner_notes": result.notes
    }

